  position: fixed;
  z-index: 2147483645;
  background: #1a1a1a;
  border: 1px solid #333;
  border-radius: 10px;
  padding: 18px 20px 14px;
  width: 320px;
  max-width: calc(100vw - 32px);
  font: 13px/1.55 -apple-system, "Segoe UI", system-ui, sans-serif;
  color: #ddd;
}
.wt-card-heading {
  font-size: 14px;
  font-weight: 600;
  color: #fff;
  margin: 0 0 12px;
}
.wt-field {
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin-bottom: 8px;
}
.wt-field-label {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: #666;
}
.wt-field-value {
  font-size: 12px;
  color: #b0b0b0;
  word-break: break-all;
}
.wt-field-value a {
  color: #4a90d9;
  text-decoration: none;
}
.wt-field-value a:hover { text-decoration: underline; }
.wt-prose {
  font-size: 13px;
  color: #bbb;
  margin: 10px 0 14px;
  line-height: 1.55;
}
.wt-nav {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}
.wt-btn {
  padding: 5px 14px;
  border-radius: 6px;
  border: 1px solid #444;
  background: #252525;
  color: #ddd;
  font: 12px -apple-system, "Segoe UI", system-ui, sans-serif;
  cursor: pointer;
  transition: background 0.1s;
}
.wt-btn:hover { background: #333; }
.wt-btn:focus-visible { outline: 2px solid #4a90d9; outline-offset: 2px; }
.wt-btn.primary {
  background: #1e4a8a;
  border-color: #2a5fa0;
  color: #fff;
}
.wt-btn.primary:hover { background: #25559a; }
.wt-counter {
  font-size: 11px;
  color: #555;
  margin-right: auto;
  align-self: center;
}

/* ── inspector popup ── */
.insp-popup {
  position: fixed;
  z-index: 2147483645;
  background: #1a1a1a;
  border: 1px solid #333;
  border-radius: 8px;
  padding: 12px 14px 10px;
  width: 280px;
  max-width: calc(100vw - 24px);
  font: 12px/1.5 -apple-system, "Segoe UI", system-ui, sans-serif;
  color: #ccc;
  pointer-events: auto;
}
.insp-popup-heading {
  font-size: 13px;
  font-weight: 600;
  color: #fff;
  margin: 0 0 8px;
}
.insp-popup-row {
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin-bottom: 7px;
}
.insp-popup-label {
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: #555;
}
.insp-popup-val {
  font-size: 12px;
  color: #aaa;
  word-break: break-all;
}
.insp-popup-val a { color: #4a90d9; text-decoration: none; }
.insp-popup-val a:hover { text-decoration: underline; }
.insp-popup-prose { font-size: 12px; color: #bbb; margin: 6px 0 10px; }
.insp-popup-actions {
  display: flex;
  gap: 6px;
  justify-content: flex-end;
}

/* ── add form ── */
.add-form {
  position: fixed;
  z-index: 2147483646;
  background: #1a1a1a;
  border: 1px solid #333;
  border-radius: 10px;
  padding: 18px 20px 14px;
  width: 340px;
  max-width: calc(100vw - 32px);
  font: 13px/1.4 -apple-system, "Segoe UI", system-ui, sans-serif;
  color: #ddd;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}
.add-form-title { font-size: 14px; font-weight: 600; color: #fff; margin: 0 0 14px; }
.add-form label { display: block; font-size: 11px; color: #666; margin-bottom: 4px; margin-top: 10px; text-transform: uppercase; letter-spacing: 0.05em; }
.add-form label:first-of-type { margin-top: 0; }
.add-form input, .add-form textarea {
  width: 100%;
  background: #111;
  border: 1px solid #333;
  border-radius: 5px;
  color: #ddd;
  font: 12px/1.4 -apple-system, "Segoe UI", system-ui, sans-serif;
  padding: 6px 8px;
  resize: vertical;
}
.add-form input:focus, .add-form textarea:focus { outline: 2px solid #4a90d9; border-color: transparent; }
.add-form textarea { min-height: 60px; }
.add-form-warn {
  margin-top: 10px;
  font-size: 11px;
  color: #c09a40;
  background: #1e1a0a;
  border: 1px solid #3a2e0a;
  border-radius: 5px;
  padding: 7px 9px;
  line-height: 1.5;
}
.add-form-warn code { font-family: monospace; color: #e0b840; }
.add-form-actions { display: flex; gap: 8px; justify-content: flex-end; margin-top: 14px; }

/* ── reduced motion ── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition: none !important; }
}
